-- Why: the domain HIGHs of the 2026-10-21 audit (H2). Holds and PENDING payments get an expiry
-- recorded at request time (MO5); payouts get one provider reference per attempt, an attempt
-- counter and a retry schedule; idempotency keys get a lease so a crashed request no longer
-- blocks its key; accounts remember who froze them and why. Generated by prisma migrate diff,
-- then edited by hand: new NOT NULL columns are added nullable, backfilled, then constrained,
-- and the CHECKs at the end are hand-written (documented with `///` on their models).

-- CreateEnum
CREATE TYPE "ReversalReason" AS ENUM ('network', 'expired', 'admin_release');

-- CreateEnum
CREATE TYPE "FreezeActor" AS ENUM ('CUSTOMER', 'ADMIN');

-- CreateEnum
CREATE TYPE "FreezeReason" AS ENUM ('customer_request', 'admin_review', 'suspected_fraud', 'collections');

-- AlterEnum (the new value is not used in this migration: Postgres refuses that in one transaction)
ALTER TYPE "PaymentStatus" ADD VALUE 'EXPIRED';

-- DropIndex (prefixes of the keyset indexes created below)
DROP INDEX "payouts_account_id_created_at_idx";

-- DropIndex
DROP INDEX "payouts_status_created_at_idx";

-- AlterTable
ALTER TABLE "accounts" ADD COLUMN     "freeze_reason" "FreezeReason",
ADD COLUMN     "frozen_at" TIMESTAMPTZ(3),
ADD COLUMN     "frozen_by" "FreezeActor";

-- AlterTable
ALTER TABLE "authorizations" ADD COLUMN     "expires_at" TIMESTAMPTZ(3),
ADD COLUMN     "reversal_reason" "ReversalReason";

-- AlterTable (backfilled below, then NOT NULL)
ALTER TABLE "collateral_deposits" ADD COLUMN     "expires_at" TIMESTAMPTZ(3);

-- AlterTable
ALTER TABLE "idempotency_keys" ADD COLUMN     "attempt" INTEGER NOT NULL DEFAULT 1,
ADD COLUMN     "locked_until" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- AlterTable (provider_reference backfilled below, then NOT NULL)
ALTER TABLE "payouts" ADD COLUMN     "attempts" INTEGER NOT NULL DEFAULT 1,
ADD COLUMN     "failed_at" TIMESTAMPTZ(3),
ADD COLUMN     "last_error" VARCHAR(64),
ADD COLUMN     "next_attempt_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
ADD COLUMN     "provider_reference" UUID;

-- AlterTable (backfilled below, then NOT NULL)
ALTER TABLE "repayments" ADD COLUMN     "expires_at" TIMESTAMPTZ(3);

-- ---------------------------------------------------------------------------------------------
-- Backfill (hand-written). Existing rows get the policies the code applies from now on.
-- ---------------------------------------------------------------------------------------------

-- Payouts already requested were sent to the provider with their own id as the reference: the
-- first attempt keeps it, so asking again can never create a second payment (MO5).
UPDATE "payouts" SET "provider_reference" = "id";
ALTER TABLE "payouts" ALTER COLUMN "provider_reference" SET NOT NULL;

-- Payments: 30 minutes after the request (PENDING_PAYMENT_TTL_MINUTES default).
UPDATE "collateral_deposits" SET "expires_at" = "created_at" + interval '30 minutes';
ALTER TABLE "collateral_deposits" ALTER COLUMN "expires_at" SET NOT NULL;
UPDATE "repayments" SET "expires_at" = "created_at" + interval '30 minutes';
ALTER TABLE "repayments" ALTER COLUMN "expires_at" SET NOT NULL;

-- Holds: 7 days after approval (HOLD_TTL_HOURS default); earlier reversals came from the network.
UPDATE "authorizations" SET "expires_at" = "created_at" + interval '7 days' WHERE "status" <> 'DECLINED';
UPDATE "authorizations" SET "reversal_reason" = 'network' WHERE "status" = 'REVERSED';

-- A card frozen before this migration: whoever froze it last, by the audit trail. When the trail
-- does not say it was the customer, it counts as an admin freeze (fail closed: the customer
-- cannot lift a freeze nobody can prove was theirs).
UPDATE "accounts" AS a
   SET "frozen_by" = CASE WHEN (
         SELECT l."actor_type" FROM "audit_log" l
          WHERE l."entity_id" = a."id"::text AND l."action" = 'account.frozen'
          ORDER BY l."created_at" DESC, l."id" DESC
          LIMIT 1) = 'customer' THEN 'CUSTOMER'::"FreezeActor" ELSE 'ADMIN'::"FreezeActor" END,
       "freeze_reason" = 'admin_review',
       "frozen_at" = a."updated_at"
 WHERE a."status" = 'FROZEN';
UPDATE "accounts" SET "freeze_reason" = 'customer_request'
 WHERE "status" = 'FROZEN' AND "frozen_by" = 'CUSTOMER';

-- CreateIndex
CREATE INDEX "authorizations_status_expires_at_idx" ON "authorizations"("status", "expires_at");

-- CreateIndex
CREATE UNIQUE INDEX "payouts_provider_reference_key" ON "payouts"("provider_reference");

-- CreateIndex
CREATE INDEX "payouts_account_id_created_at_id_idx" ON "payouts"("account_id", "created_at" DESC, "id" DESC);

-- CreateIndex
CREATE INDEX "payouts_created_at_id_idx" ON "payouts"("created_at" DESC, "id" DESC);

-- CreateIndex
CREATE INDEX "payouts_status_created_at_id_idx" ON "payouts"("status", "created_at" DESC, "id" DESC);

-- CreateIndex
CREATE INDEX "payouts_status_next_attempt_at_idx" ON "payouts"("status", "next_attempt_at");

-- ---------------------------------------------------------------------------------------------
-- Hand-written CHECKs: what Prisma cannot express. Each is documented with `///` on its model.
-- ---------------------------------------------------------------------------------------------

-- An approved hold always carries its expiry; a decline holds nothing. A reversal says why.
ALTER TABLE "authorizations"
  ADD CONSTRAINT "authorizations_expiry" CHECK (("status" = 'DECLINED') = ("expires_at" IS NULL)),
  ADD CONSTRAINT "authorizations_reversal_reason" CHECK (("status" = 'REVERSED') = ("reversal_reason" IS NOT NULL));

-- Who froze the card, and why, is known exactly while it is frozen.
ALTER TABLE "accounts"
  ADD CONSTRAINT "accounts_frozen_by" CHECK (
    ("status" = 'FROZEN') = ("frozen_by" IS NOT NULL)
    AND ("frozen_by" IS NULL) = ("freeze_reason" IS NULL)
    AND ("frozen_by" IS NULL) = ("frozen_at" IS NULL)
  );

ALTER TABLE "payouts"
  ADD CONSTRAINT "payouts_attempts_positive" CHECK ("attempts" >= 1);
